import 'package:flutter/material.dart';import 'api.dart';
class PermissionMatrixScreen extends StatefulWidget{const PermissionMatrixScreen({super.key});@override State<PermissionMatrixScreen> createState()=>_State();}
class _State extends State<PermissionMatrixScreen>{List data=[];final nodes=const['can_delete_posts','can_ban_members','can_host_events','can_pin_announcements','can_approve_membership','can_moderate_chat'];Future<void> load()async{final x=await adminApi.permissions();if(mounted)setState(()=>data=x);}@override void initState(){super.initState();load();}@override Widget build(BuildContext c)=>ListView(children:data.map((p)=>ExpansionTile(title:Text(p['admin_username']??''),children:nodes.map((n)=>SwitchListTile(title:Text(n),value:p[n]??false,onChanged:(v)async{await adminApi.setPermission(p['id'],n,v);load();})).toList())).toList());}
